e'] ?? '') ?>" required></label><label class="span-all">Programme d’entraînement *<textarea name="content" maxlength="10000" rows="5" required><?= e($_POST['content'] ?? '') ?></textarea></label><div class="form-actions"><button class="primary">Créer le programme</button></div></form></details></div>
<?php if ($measurements): $last=$measurements[0]; $bmi=(float)$last['weight_kg']/(((float)$last['height_cm']/100)**2); ?><section class="stats fitness-stats"><article class="stat-card"><div class="stat-label">Dernier poids</div><div class="stat-value"><?= e(number_format((float)$last['weight_kg'],2,',',' ')) ?> kg</div><div class="stat-footer"><?= e(date('d/m/Y',strtotime($last['measured_on']))) ?></div></article><article class="stat-card"><div class="stat-label">Dernière taille</div><div class="stat-value"><?= e(number_format((float)$last['height_cm'],2,',',' ')) ?> cm</div><div class="stat-footer">Saisie avec le poids</div></article><article class="stat-card"><div class="stat-label">IMC calculé</div><div class="stat-value"><?= e(number_format($bmi,1,',',' ')) ?></div><div class="stat-footer">Indicateur non diagnostique</div></article></section><section class="card management-table"><div class="card-head"><div><h3>Évolution du poids</h3><p>Jusqu’aux 100 dernières mesures enregistrées</p></div></div><div class="chart-wrap"><canvas id="fitnessChart" aria-label="Évolution du poids en kilogrammes" role="img"></canvas></div></section><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Historique des mesures</h3><p>Les 100 dernières mesures</p></div></div><div class="table-scroll"><table><thead><tr><th>DATE</th><th>POIDS</th><th>TAILLE</th><th>TOUR DE TAILLE</th><th>IMC</th><th>NOTES</th></tr></thead><tbody><?php foreach ($measurements as $m): ?><tr><td><?= e(date('d/m/Y',strtotime($m['measured_on']))) ?></td><td><?= e($m['weight_kg']) ?> kg</td><td><?= e($m['height_cm']) ?> cm</td><td><?= $m['waist_cm'] !== null ? e($m['waist_cm']).' cm' : '—' ?></td><td><?= e(number_format((float)$m['weight_kg']/(((float)$m['height_cm']/100)**2),1,',',' ')) ?></td><td><?= e($m['notes'] ?: '—') ?></td></tr><?php endforeach; ?><?php if (!$measurements): ?><tr><td colspan="6" class="empty">Aucune mesure enregistrée.</td></tr><?php endif; ?></tbody></table></div><p class="form-hint">L’IMC est un indicateur indicatif et ne constitue pas un diagnostic médical.</p></section>
<section class="card management-table"><div class="card-head"><div><h3>Objectifs & programmes</h3><p>Les 100 derniers programmes</p></div></div><?php foreach ($programs as $program): ?><article class="program-item"><div class="card-head"><div><h3><?= e($program['title']) ?></h3><p><?= e(date('d/m/Y',strtotime($program['created_at']))) ?> · <?= $program['status']==='active' ? 'Actif' : 'Archivé' ?></p></div><?php if ($program['status']==='active'): ?><form method="post" action="index.php?page=fitness"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="member_id" value="<?= (int)$memberId ?>"><input type="hidden" name="program_id" value="<?= (int)$program['id'] ?>"><button class="link-button" onclick="return confirm('Archiver ce programme ?')">Archiver</button></form><?php endif; ?></div><p><strong>Objectif :</strong> <?= e($program['objective']) ?></p><div class="program-content"><?= e($program['content']) ?></div></article><?php endforeach; ?><?php if (!$programs): ?><p class="empty">Aucun programme pour ce membre.</p><?php endif; ?></section>
<?php if ($measurements): $chronological=array_reverse($measurements); ?><script>window.fitnessData = <?= json_encode(['labels'=>array_map(fn($m)=>date('d/m/Y',strtotime($m['measured_on'])),$chronological),'values'=>array_map(fn($m)=>(float)$m['weight_kg'],$chronological)],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;</script><?php endif; ?><?php endif; ?>
